class Inventory {
  #items = [];
  [Symbol.iterator]() {
    const items = this.#items;
    let i = 0;
    return { next: () => i < items.length
        ? { value: items[i++], done: false }
        : { value: undefined, done: true } };
  }
}
for (const item of inventory) use(item);   // for-of / spread / destructuring

